export type DocumentRow = {
    /**
     * Fixed for the life of the row (R-DOC-02).
     */
    id: string;
    position: number;
    /**
     * Goes up by one each time the row is saved. Send it back when changing the row (R-DOC-07).
     */
    version: number;
    process_id?: string;
    process_name?: string;
    operation_number?: string;
    /**
     * The operation number was typed or pasted, so automatic numbering keeps it (M4.6).
     */
    operation_manual: boolean;
    /**
     * The link to the template point was cut, with a reason (M4.8).
     */
    detached: boolean;
    /**
     * The section of the row (D-155); left out for a document without sections.
     */
    section_id?: string;
    detach_reason?: string;
    /**
     * Row content keyed by column field ID.
     */
    content: {
        [key: string]: unknown;
    };
    /**
     * The process template point this row was composed from; left out for a typed or pasted row (R-CMP-04).
     */
    template_point_id?: string;
};

export type DocumentRowInput = {
    process_id?: string;
    operation_number?: string;
    content: {
        [key: string]: unknown;
    };
    /**
     * The section of a new row; required when the document has sections (D-155). Ignored when changing a row.
     */
    section_id?: string;
    /**
     * The version of the row that was read. Required when changing a row, ignored when adding one. When the row was changed by someone else in the meantime the answer is 409 with code changed, and nothing is saved (optimistic locking, R-DOC-07).
     */
    version?: number;
};

